%% CPR main analysis
% Processes and analyses CPR electrophysiology data.
%
% Required per recording:
%   .MWK2   MWorks data file
%   .MAT    spike files generated by ULTRAsort
%
% Pipeline stages (in order):
%   1. Write wideband data
%   2. Check clipping
%   3. ULTRAsort preprocessing (no denoising)
%   4. ULTRAsort spike sorting (negative threshold channels only)
%   5. PHY_preprocessing  — import, sync, RF characterisation, CPR spikes
%   6. PHY_quality_assessment — onset response test, inclusion flags
%   7. PHY_sort_spikes_by_state — state-aligned spike trains
%
% Felix Schneider, CNL
%
% Version history
%   1.0  (fxs 2025-09-05)  Initial version.
%   1.1  (fxs 2025-xx-xx)  RF_characterisation integrated into preprocessing.
%
% TO DO
%   (1) Drift analysis — check FR stability over time
%   (2) Optional spike-free (behaviour-only) mode

clear; close all;

addpath('/Users/cnl/Desktop/CPR/code');


% =========================================================================
%% Configuration
% =========================================================================

cfg_pth      = '/Users/cnl/Desktop/CPR/code/felix_nhp_solo.cfg';
source_dir   = '/Users/cnl/Documents/DATA/Nilan/';
preproc_flag = true;    % true  = run full preprocessing pipeline
                        % false = load previously saved summary file
import_flag  = false;   % true  = import from .mwk2 and write .h5
                        % false = load existing .h5


% =========================================================================
%% Recording list
% =========================================================================
% Each entry is a full recording identifier string.
% Recordings excluded from the list are documented below with the reason.

rec_lst = {
    '20250924_nil_CPR_block1_phy4_rec059_fxs', ...
    '20250925_nil_CPR_block1_phy4_rec060_fxs', ...
    '20250926_nil_CPR_block1_phy4_rec061_fxs', ...
    '20251204_nil_CPR_block1_phy4_rec068_fxs', ...
    '20260128_nil_CPR_block1_phy4_rec074_ann', ...
    '20260123_nil_CPR_block2_phy4_rec073_ann'};

% Excluded recordings:
%   20250807_nil_..._rec045  onset transients before t=0
%   20250903_nil_..._rec050  (commented out — under review)
%   20251001_nil_..._rec063  sorted but sync issues
%   20251024_nil_..._rec066  channel clipping
%   20251205_nil_..._rec069  no A/D data
%   20251211_nil_..._rec070  no A/D data


% =========================================================================
%% Main processing loop
% =========================================================================

for iRec = 1:numel(rec_lst)

    rec_name = rec_lst{iRec};
    rec_info = split(rec_name, '_');

    % Build destination directory from date, recording number, and block
    dest_dir = fullfile('/Users/cnl/Documents/DATA/Nilan/spike_sorting/', ...
                        sprintf('%s_%s_%s', rec_info{1}, rec_info{6}, rec_info{4}), '/');

    summary_file = fullfile(dest_dir, ['summary_' rec_name '.mat']);
    state_file   = fullfile(dest_dir, ['state_responses_' rec_name '.mat']);

    fprintf('\n%s\n', repmat('=', 1, 70));
    fprintf('  Recording %d / %d:  %s\n', iRec, numel(rec_lst), rec_name);
    fprintf('%s\n', repmat('=', 1, 70));

    % -----------------------------------------------------------------
    % Stage 1 — Preprocessing
    % -----------------------------------------------------------------
    if preproc_flag
        fprintf('  [1/3]  Preprocessing...\n');
        phy = PHY_preprocessing_v2(rec_name, source_dir, dest_dir, cfg_pth, import_flag);
    else
        fprintf('  [1/3]  Loading saved summary...\n');
        load(summary_file, 'phy');
    end

    % -----------------------------------------------------------------
    % Stage 2 — Quality assessment
    %   Tests onset responses, assigns inclusion flags, stores results
    %   in phy.brain.CPR.spks.include.
    % -----------------------------------------------------------------
    fprintf('  [2/3]  Quality assessment...\n');
    phy = PHY_quality_assessment(phy);

    save(summary_file, 'phy', '-v7.3');
    fprintf('         Saved: %s\n', summary_file);

    % -----------------------------------------------------------------
    % Stage 3 — Sort spikes by stimulus state
    %   Aligns spike trains to each RDP direction-change event and
    %   computes per-state spike density functions.
    % -----------------------------------------------------------------
    fprintf('  [3/3]  Sorting spikes by state...\n');
    state = PHY_sort_spikes_by_state(phy);

    save(state_file, 'state', '-v7.3');
    fprintf('         Saved: %s\n', state_file);

end

fprintf('\nAll recordings processed.\n');


