function state = PHY_sort_spikes_by_state(in)
% PHY_SORT_SPIKES_BY_STATE  Align spike trains and behaviour to each RDP
%                           direction-change event within a CPR cycle.
%
% For every state (direction epoch) within every CPR cycle the function
% extracts: stimulus parameters, outcome, joystick trajectories, and
% per-unit spike timestamps aligned to state onset.  A spike density
% function (alpha kernel) is also computed per unit per state.

clear state
state_cnt = 0;
stim      = in.stim;
joy       = in.joy;

for iCyc = 1:numel(stim.rdp_dir)
    for iState = 2:numel(stim.rdp_dir{iCyc})   % discard inherited direction from previous cycle

        state_cnt = state_cnt + 1;

        % --- Task flag ---------------------------------------------------
        state.cpr_solo(state_cnt) = stim.cpr_solo{iCyc};

        % --- Stimulus parameters -----------------------------------------
        state.rdp_dir(state_cnt)    = stim.rdp_dir{iCyc}(iState);
        state.rdp_dir_ts(state_cnt) = stim.rdp_dir_ts{iCyc}(iState);

        % Coherence is inherited from the most recent coherence event
        state.rdp_coh(state_cnt) = stim.rdp_coh{iCyc}( ...
            find(state.rdp_dir_ts(state_cnt) >= stim.rdp_coh_ts{iCyc}, 1, 'last'));

        % State boundaries: [onset timestamp, offset timestamp]
        is_last_state = iState == numel(stim.rdp_dir{iCyc});
        if is_last_state
            state_end = double(stim.cpr_cyle(iCyc, 2));
        else
            state_end = stim.rdp_dir_ts{iCyc}(iState + 1);
        end
        state.boundaries(state_cnt, :) = [stim.rdp_dir_ts{iCyc}(iState), state_end];
        state.dur_s(state_cnt)         = double(state_end - stim.rdp_dir_ts{iCyc}(iState)) / 1e6;
        state.cIdx(state_cnt)          = iCyc;

        % --- Feedback and outcome ----------------------------------------
        trg_idx = stim.feedback_ts{iCyc} > stim.rdp_dir_ts{iCyc}(iState) & ...
                  stim.feedback_ts{iCyc} < state_end;

        state.feedback_state_ts_raw{state_cnt} = stim.feedback_ts{iCyc}(trg_idx);

        % Feedback latency in ms and frame samples (120 Hz display)
        dt_us = stim.feedback_ts{iCyc}(trg_idx) - stim.rdp_dir_ts{iCyc}(iState);
        state.feedback_state_ms{state_cnt}    = dt_us ./ 1e3;
        state.feedback_state_smple{state_cnt} = ceil((dt_us ./ 1e3) ./ (1000/120));

        state.outcome{state_cnt}   = stim.outcome{iCyc}(trg_idx);
        state.reward_cum{state_cnt}= stim.reward_cum{iCyc}(trg_idx);
        state.score_cum{state_cnt} = stim.score_cum{iCyc}(trg_idx);

        % --- Joystick trajectories ---------------------------------------
        js_monk_idx = joy.js_monk_ts{iCyc} > stim.rdp_dir_ts{iCyc}(iState) & ...
                      joy.js_monk_ts{iCyc} < state_end;
        js_hum_idx  = joy.js_hum_ts{iCyc}  > stim.rdp_dir_ts{iCyc}(iState) & ...
                      joy.js_hum_ts{iCyc}  < state_end;

        state.js_monk_tlt{state_cnt} = joy.js_monk_tlt{iCyc}(js_monk_idx);
        state.js_monk_dir{state_cnt} = joy.js_monk_dir{iCyc}(js_monk_idx);
        state.js_hum_tlt{state_cnt}  = joy.js_hum_tlt{iCyc}(js_hum_idx);
        state.js_hum_dir{state_cnt}  = joy.js_hum_dir{iCyc}(js_hum_idx);

        % --- Spike trains per included unit ------------------------------
        for iUnit = 1:numel(in.brain.CPR.spks.include.unit_ID)

            if ~in.brain.CPR.spks.include.inclusion_flag(iUnit)
                continue
            end

            unit_str  = in.brain.CPR.spks.include.unit_ID{iUnit};
            chan_part = unit_str(1:9);    % e.g. 'ch001_neg'
            unit_part = unit_str(11:end); % e.g. 'unit2'

            dat = in.brain.CPR.spks.(chan_part).(unit_part);

            % Spike index relative to cycle onset (dat already cycle-aligned)
            cycle_onset = double(stim.cpr_cyle(iCyc, 1));
            spk_idx = dat{iCyc} > stim.rdp_dir_ts{iCyc}(iState) - cycle_onset & ...
                      dat{iCyc} < state_end - cycle_onset;

            % State-aligned spike timestamps (relative to state onset)
            state_onset_rel                       = stim.rdp_dir_ts{iCyc}(iState) - cycle_onset;
            state.spk_n.(unit_str)(state_cnt)     = sum(spk_idx);
            state.spk_ts.(unit_str){state_cnt}    = dat{iCyc}(spk_idx) - state_onset_rel;

            % Alpha-kernel spike density function over state duration
            time = 0 : 0.001 : state.dur_s(state_cnt);
            if state.spk_n.(unit_str)(state_cnt) > 0
                alpha_kern                         = fit_alpha(state.spk_ts.(unit_str){state_cnt} ./ 1e6, time);
                state.sdf.(unit_str){state_cnt}    = sum(alpha_kern, 1);
            else
                state.sdf.(unit_str){state_cnt}    = zeros(1, numel(time));
            end

            % Inclusion flag: was this cycle in the unit's analysis range?
            cyc_ids = in.brain.CPR.spks.include.cyc_id{iUnit};
            state.include.(unit_str)(state_cnt) = ismember(iCyc, cyc_ids);

        end % iUnit
    end % iState
end % iCyc

end % PHY_sort_spikes_by_state


function out = concat_coh_blocks(var_in, cbound)
% CONCAT_COH_BLOCKS  Concatenate data within coherence block boundaries.

for iBlock = 1:numel(cbound) - 1
    seg = var_in(cbound(iBlock) : cbound(iBlock+1) - 1);
    if iscell(seg)
        out{iBlock} = cell2mat(seg);
    else
        out(iBlock) = unique(seg);
    end
end

end % concat_coh_blocks


function gauss = fit_gaussian(spks, time)
% FIT_GAUSSIAN  Fit a Gaussian kernel centred on each spike time.

sigma = 0.005;   % kernel width in seconds

for iSpk = 1:numel(spks)
    mu           = spks(iSpk);
    gauss(iSpk,:)= exp(-0.5 .* ((time - mu) ./ sigma).^2) ./ (sigma * sqrt(2*pi));
end

end % fit_gaussian


function alpha = fit_alpha(spks, time)
% FIT_ALPHA  Fit a causal alpha kernel centred on each spike time.
%            Normalised to unit area for rate estimation in Hz.

tau   = 0.005;   % kernel time constant in seconds
nSpks = numel(spks);
nTime = numel(time);
alpha = zeros(nSpks, nTime);

for iSpk = 1:nSpks
    t_rel       = time - spks(iSpk);
    k           = zeros(1, nTime);
    causal      = t_rel >= 0;
    k(causal)   = (t_rel(causal) ./ tau) .* exp(1 - t_rel(causal) ./ tau);
    alpha(iSpk,:) = k / (exp(1) * tau);   % normalise to unit area
end

end % fit_alpha


function [all_spks, sdf_g, sdf_a] = FR_estimation(spike_times, time, plot_flag)
% FR_ESTIMATION  Estimate firing rate from spike times using Gaussian and
%                alpha kernel spike density functions.
%
% INPUT
%   spike_times  cell [nTrials×1]  spike timestamps in seconds per trial
%   time         [1×nSamples]      time axis in seconds
%   plot_flag    logical            true = draw raster

all_spks = [];
sdf_g    = [];
sdf_a    = [];

for iTrial = 1:numel(spike_times)
    spks     = double(spike_times{iTrial}') ./ 1e6;
    all_spks = [all_spks, spks];

    % Raster plot — each trial is a row, each spike a vertical tick
    if plot_flag && ~isempty(spks)
        xspk      = repmat(spks, 3, 1);
        yspk      = nan(size(xspk));
        yspk(1,:) = iTrial - 1;
        yspk(2,:) = iTrial;
        plot(xspk, yspk, 'Color', 'k', 'LineWidth', 1.25);
    end

    if ~isempty(spks)
        sdf_g(iTrial,:) = sum(fit_gaussian(spks, time), 1);
        sdf_a(iTrial,:) = sum(fit_alpha(spks, time),    1);
    end
end

end % FR_estimation


function out = test_onset_response(spks_cyc)
% TEST_ONSET_RESPONSE  Test whether a unit shows a significant onset
%                      response in the first 500 ms after cycle start.
%
% Uses an alpha-kernel SDF averaged across cycles.  Significance is
% assessed by a Wilcoxon signed-rank test (baseline vs stimulus window)
% and a threshold-crossing latency estimate (3 SD above/below baseline).

% Crop to first 1000 ms to keep computation fast
for iCyc = 1:numel(spks_cyc)
    spks_cyc{iCyc}(spks_cyc{iCyc} > 1e6) = [];
end

% Build average SDF across cycles
tstep = 0.001;
time  = -0.3 : tstep : 1.0;

[~, ~, sdf_a] = FR_estimation(spks_cyc, time, false);

% Safe return if no spikes found in any cycle
if isempty(sdf_a)
    out = struct('mean_fr', NaN, 'lat', NaN, 'p', NaN, 'h', NaN, ...
                 'stats', struct('zval', NaN));
    return
end

msdf = mean(sdf_a, 1);   % mean SDF across cycles

% Time windows (sample indices):  baseline = −300 to 0 ms,  stimulus = 0 to 200 ms
BL_idx   = 1  : 300;
stim_idx = 301 : 500;
out.mean_fr = mean(msdf(stim_idx));

% Wilcoxon signed-rank test on per-cycle window averages
mBL   = mean(sdf_a(:, BL_idx),   2);
mStim = mean(sdf_a(:, stim_idx), 2);
[out.p, out.h, out.stats] = signrank(mStim, mBL);

if ~isfield(out.stats, 'zval')
    out.stats.zval = NaN;
end

% Threshold-crossing latency: first run of ≥10 consecutive bins that
% all exceed the baseline mean ± 3 SD
n_std  = 3;
n_bins = 9;   % 9+1 = 10 consecutive bins required
thresh = [mean(msdf(BL_idx)) + n_std * std(msdf(BL_idx)), ...
          mean(msdf(BL_idx)) - n_std * std(msdf(BL_idx))];

exc = zeros(1, numel(time));
for s = stim_idx(1) : stim_idx(end) - n_bins
    window = msdf(s : s + n_bins);
    if all(window >= thresh(1)) || all(window <= thresh(2))
        exc(s) = s;
    end
end

first_cross = find(exc, 1, 'first');
if ~isempty(first_cross)
    out.lat = first_cross - stim_idx(1);   % latency in ms relative to stim onset
else
    out.lat = NaN;
end

end % test_onset_response


function phy = PHY_quality_assessment(phy)
% PHY_QUALITY_ASSESSMENT  Test onset responses and assign inclusion flags.
%
% For every sorted unit on every channel:
%   1. Manually define stable analysis ranges (cycle subsets).
%   2. Test onset response against baseline using a Wilcoxon test and
%      a threshold-crossing latency estimate.
%   3. Apply inclusion criteria and store results in phy.brain.CPR.spks.include.
%
% Inclusion criteria (all must be met):
%   - ≥ 30 cycles in the analysis range
%   - Significant onset response (p < 0.05, Wilcoxon signed-rank)
%   - Mean firing rate ≥ 1 Hz
%   - Onset latency between 35 and 200 ms

% Table schema
var_names  = {'unit_ID','n_Cycles','mean_FR','signrank_p','signrank_z', ...
              'thresh_latency_ms','inclusion_flag'};
var_types  = {'string','double','double','double','double','double','logical'};
t          = table('Size', [1000, numel(var_names)], ...
                   'VariableTypes', var_types, ...
                   'VariableNames', var_names);

% Inclusion thresholds
min_cycles   = 30;
min_dur_s    = 5;
min_fr       = 1;
p_thresh     = 0.05;
min_lat_ms   = 35;
max_lat_ms   = 200;

chan_lst = fieldnames(phy.brain.CPR.spks);
chan_lst(strcmp(chan_lst, 'include')) = [];

cc = 0;   % row counter

for iChan = 1:numel(chan_lst)
    unit_lst = fieldnames(phy.brain.CPR.spks.(chan_lst{iChan}));

    for iUnit = 1:numel(unit_lst)

        % Skip unsorted noise cluster
        if strcmp(unit_lst{iUnit}, 'unit0')
            continue
        end

        spk_times_cyc = phy.brain.CPR.spks.(chan_lst{iChan}).(unit_lst{iUnit});

        % Manually assign stable analysis ranges for this unit
        mask = manually_assign_analysis_range(phy, chan_lst{iChan}, unit_lst{iUnit});

        for iRange = 1:size(mask, 2)
            cc           = cc + 1;
            range_suffix = sprintf('_range%d', iRange);
            t.unit_ID(cc)= string([chan_lst{iChan} '_' unit_lst{iUnit} range_suffix]);

            cycles_in_range = spk_times_cyc(mask(:, iRange));
            n_valid         = sum(mask(:, iRange));

            if n_valid >= min_cycles
                res = test_onset_response(cycles_in_range);

                t.n_Cycles(cc)          = n_valid;
                t.cyc_id{cc}            = find(mask(:, iRange));
                t.mean_FR(cc)           = res.mean_fr;
                t.signrank_p(cc)        = res.p;
                t.signrank_z(cc)        = res.stats.zval;
                t.thresh_latency_ms(cc) = res.lat;

                % All four criteria must be satisfied for inclusion
                lat_ok  = res.lat  >  min_lat_ms && res.lat < max_lat_ms;
                p_ok    = res.p    <  p_thresh;
                fr_ok   = res.mean_fr > min_fr;
                n_ok    = n_valid  >= min_cycles;
                t.inclusion_flag(cc) = lat_ok && p_ok && fr_ok && n_ok;

            else
                % Not enough cycles — flag as excluded
                t.n_Cycles(cc)          = NaN;
                t.cyc_id{cc}            = NaN;
                t.mean_FR(cc)           = NaN;
                t.signrank_p(cc)        = NaN;
                t.signrank_z(cc)        = NaN;
                t.thresh_latency_ms(cc) = NaN;
                t.inclusion_flag(cc)    = false;
            end
        end % iRange
    end % iUnit
end % iChan

% Remove unused pre-allocated rows and store
t(ismissing(t.unit_ID), :)  = [];
phy.brain.CPR.spks.include  = t;

end % PHY_quality_assessment

