function out = PHY_sort_spikes_by_coherence(in)
% PHY_SORT_SPIKES_BY_COHERENCE  Group state-level data into coherence blocks.

out.coh          = [];
out.js_monk_dir  = [];
out.js_monk_tlt  = [];
out.js_hum_dir   = [];
out.js_hum_tlt   = [];
out.reward_cum   = [];
out.outcome      = [];

for iCyc = 1:in.cIdx(end)
    cIdx   = in.cIdx == iCyc;
    cbound = [find(cIdx, 1, 'first'), ...
              find(cIdx, 1, 'first') + find(diff(in.rdp_coh(cIdx))), ...
              find(cIdx, 1, 'last') + 1];

    out.coh         = [out.coh,        concat_coh_blocks(in.rdp_coh,       cbound)];
    out.js_monk_dir = [out.js_monk_dir, concat_coh_blocks(in.js_monk_dir,   cbound)];
    out.js_monk_tlt = [out.js_monk_tlt, concat_coh_blocks(in.js_monk_tlt,   cbound)];
    out.js_hum_dir  = [out.js_hum_dir,  concat_coh_blocks(in.js_hum_dir,    cbound)];
    out.js_hum_tlt  = [out.js_hum_tlt,  concat_coh_blocks(in.js_hum_tlt,    cbound)];
    out.reward_cum  = [out.reward_cum,  concat_coh_blocks(in.reward_cum,     cbound)];
end

end % PHY_sort_spikes_by_coherence

function T = convert2table(state, varargin)
% CONVERT2TABLE  Convert the state struct to a tidy table.
%
% Spike times for excluded trials are replaced with empty cells.
% Units with no valid trials can optionally be dropped.

p = inputParser;
addParameter(p, 'RemoveEmptyUnits', true, @islogical);
parse(p, varargin{:});
remove_empty = p.Results.RemoveEmptyUnits;

n_trials    = numel(state.cpr_solo);
all_fields  = fieldnames(state);
skip_fields = {'spk_ts','spk_n','include'};
data_fields = setdiff(all_fields, skip_fields);

% Build table from trial-wise scalar and cell fields
T = table();
for i = 1:numel(data_fields)
    f   = data_fields{i};
    val = state.(f);
    if (isvector(val) && numel(val) == n_trials) || ...
       (iscell(val)   && numel(val) == n_trials)
        T.(f) = val(:);
    else
        warning('convert2table: skipping field ''%s'' (unsupported size/type).', f);
    end
end

% Reorder to a fixed canonical column sequence
desired_order = {'cIdx','cpr_solo','dur_s','feedback_state_smple', ...
                 'outcome','reward_cum','rdp_coh','rdp_dir','rdp_dir_ts', ...
                 'js_hum_dir','js_hum_tlt','js_monk_dir','js_monk_tlt'};
T = T(:, desired_order);

% Append spike timestamps as one column per unit
unit_names = {};
if isfield(state, 'spk_ts')
    unit_names = fieldnames(state.spk_ts);
    for i = 1:numel(unit_names)
        T.(unit_names{i}) = state.spk_ts.(unit_names{i})(:);
    end
end

% Zero out spike columns for excluded trials
if isfield(state, 'include')
    for i = 1:numel(unit_names)
        u = unit_names{i};
        if isfield(state.include, u)
            spk_col          = T.(u);
            spk_col(~state.include.(u)(:)) = {[]};
            T.(u)            = spk_col;
        end
    end
end

% Optionally drop units that have no valid trials at all
if remove_empty && isfield(state, 'include')
    keep = false(size(unit_names));
    for i = 1:numel(unit_names)
        u       = unit_names{i};
        keep(i) = isfield(state.include, u) && any(state.include.(u));
    end
    T(:, unit_names(~keep)) = [];
    unit_names = unit_names(keep);
end

% Move spike columns to the rightmost position
existing_unit_cols = intersect(unit_names, T.Properties.VariableNames);
if ~isempty(existing_unit_cols)
    T = movevars(T, existing_unit_cols, 'After', width(T));
end

end % convert2table


function mask = manually_assign_analysis_range(phy, chan, clus)
% MANUALLY_ASSIGN_ANALYSIS_RANGE  Interactively define stable cycle ranges.
%
% Plots a raster of the first 2 s of each cycle for the given unit.
% The user enters the number of stable clusters and their cycle ranges.
% The resulting logical mask is saved to disk and reloaded on subsequent
% calls so the interactive step is skipped.

dest_dir = fullfile('/Users/cnl/Documents/DATA/Nilan/spike_sorting/', ...
    [phy.exp.date '_' phy.exp.rec_num '_' phy.exp.block], 'inclusion_mask/');

if ~isfolder(dest_dir)
    mkdir(dest_dir);
end

mask_file = fullfile(dest_dir, [chan '_' clus '.mat']);
disp([chan '_' clus]);

% Return saved mask if it already exists
if isfile(mask_file)
    load(mask_file, 'mask');
    return
end

% Crop spike trains to first 2 s for display
n_cyc = numel(phy.stim.cpr_cyle);
cpr_spk_times = cell(1, n_cyc);
for iCyc = 1:n_cyc
    ts = double(phy.brain.CPR.spks.(chan).(clus){iCyc});
    cpr_spk_times{iCyc} = ts(ts <= 2e6);
end

N = n_cyc;
time = 0 : 0.001 : 2.0;

n_non_empty = N - sum(cellfun(@isempty, cpr_spk_times));
if n_non_empty < 30
    % Too few spikes to be worth curating — exclude entirely
    mask  = false(N, 1);
    nClus = 0;
else
    figure; hold on; grid on;
    FR_estimation(cpr_spk_times, time, true);
    fprintf('  Total cycles: %d\n', N);
    nClus = input('  Number of stable clusters to define (0 = exclude all): ');
end

if nClus == 0
    mask = false(N, 1);
else
    mask = false(N, nClus);
    for i = 1:nClus
        rng_i = input(sprintf('  Range %d — enter as [start_cycle end_cycle]: ', i));
        mask(rng_i(1):rng_i(2), i) = true;
    end
end

save(mask_file, 'mask');

end % manually_assign_analysis_range